11	)
12	
13	// backgroundPausedFile is machine-level, beside the watch plan, because the
14	// thing it pauses — the one watcher and every worker it and the hooks launch —
15	// is machine-level too.
16	const backgroundPausedFile = "paused"
17	
18	func backgroundPausedPath(env EntireEnv) (string, error) {
19		dirs, err := base.ResolvePluginDirs(env)
20		if err != nil {
21			return "", fmt.Errorf("resolve plugin state dir: %w", err)
22		}
23		return filepath.Join(dirs.State, backgroundPausedFile), nil
24	}
25	
26	// backgroundPaused fails open: a state dir that cannot be resolved or read
27	// means "not paused", because a brain that silently stops updating is worse
28	// than one that keeps going after a pause it could not see.
29	func backgroundPaused(env EntireEnv) bool {
30		path, err := backgroundPausedPath(env)
31		if err != nil {
32			return false
33		}
34		_, err = os.Stat(path)
35		return err == nil
36	}
37	
38	func setBackgroundPaused(env EntireEnv, paused bool) error {
39		path, err := backgroundPausedPath(env)
40		if err != nil {
41			return err
42		}
43		if !paused {
44			if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
45				return err
46			}
47			return nil
48		}
49		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
50			return err
51		}
52		return os.WriteFile(path, nil, 0o600)
53	}
54	
55	func newStopCommand(opts Options) *cobra.Command {
56		return &cobra.Command{
57			Use:   "stop",
58			Short: "Pause background brain work on this machine",
59			Long: "Pause background brain work on this machine until `start`.\n\n" +
60				"From its next pass every watcher, installed or run by hand, idles, memory\n" +
61				"workers exit without working, the session-end hook skips its refresh and\n" +
62				"distill, and `setup` skips its backfill. A pass already running, such as a\n" +
63				"`setup` backfill (capped at --backfill-budget sessions), finishes first.\n\n" +
64				"Nothing is lost: captured sessions stay canonical and are picked up by the\n" +
65				"watcher, the next hook, or a re-run `setup` once `start` lifts the pause.",
66			Args: cobra.NoArgs,
67			RunE: func(cmd *cobra.Command, args []string) error {
68				if err := setBackgroundPaused(opts.Env, true); err != nil {
69					return fmt.Errorf("pause background work: %w", err)
70				}
71				fmt.Fprintf(cmd.OutOrStdout(), "background brain work paused; passes already running finish first (`%s start` resumes)\n", base.SetupCommandPrefix(os.LookupEnv))
72				return nil
73			},
74		}
75	}
76	
77	func newStartCommand(opts Options) *cobra.Command {
78		return &cobra.Command{
79			Use:   "start",
80			Short: "Resume background brain work paused by `stop`",
81			Args:  cobra.NoArgs,
82			RunE: func(cmd *cobra.Command, args []string) error {
83				if err := setBackgroundPaused(opts.Env, false); err != nil {
84					return fmt.Errorf("resume background work: %w", err)
85				}
86				fmt.Fprintln(cmd.OutOrStdout(), "background brain work resumed")
87				return nil
88			},
89		}
90	}
